  cpa: [
  { lat:49.23226, lng:5.25198, loc:"Le Mort-Homme (Meuse)", p:1, stopId:102, cpa:[
    { img:"cartes_postales/mort_homme_attaque_1916.jpg",
      title:"Assaut sur le Mort-Homme — mars 1916",
      desc:"Juin 1940. La colonne longe la rive gauche de la Meuse sous les détonations de l'artillerie qui brûle ses réserves d'obus. À un carrefour, une pancarte : <em>« Le Mort-Homme 1 km 500 »</em>. « Ça me rappelle quelque chose », écrit Alban — ce nom de la Grande Guerre, où des milliers d'hommes moururent pour cette butte en 1916. Ici : soldats allemands quittant leurs tranchées à l'assaut du Mort-Homme, 14-15 mars 1916. Photo : Hermann Rex. <a href=\"https://fr.wikipedia.org/wiki/Le_Mort-Homme\" target=\"_blank\" style=\"color:#c8a96e\">↗ Wikipedia : Le Mort-Homme</a>" },
    { img:"cartes_postales/mort_homme_carte_1917.png",
      title:"Carte : Mort-Homme et Côte 304, rive gauche Meuse (1917)",
      desc:"La rive gauche de la Meuse en 1916-1917. Le Mort-Homme (côte 295) et la Côte 304 — les deux buttes que Coco désigne comme point de rendez-vous avec le commandant d'artillerie. En juin 1940, la colonne du 11e R.I. les longe en retraite. <a href=\"https://fr.wikipedia.org/wiki/Le_Mort-Homme\" target=\"_blank\" style=\"color:#c8a96e\">↗ Wikipedia : Le Mort-Homme</a>" },
    { img:"cartes_postales/mort_homme_trichterfeld.jpg",
      title:"Champ de cratères du Mort-Homme (Trichterfeld)",
      desc:"Le paysage lunaire que la colonne longe en juin 1940 : des hectares de cratères d'obus creusés en 1916. <em>Im Trichterfeld des Toten Mannes</em> — « Dans le champ de trous du Mort-Homme ». La butte elle-même avait été rasée par les bombardements. <a href=\"https://fr.wikipedia.org/wiki/Le_Mort-Homme\" target=\"_blank\" style=\"color:#c8a96e\">↗ Wikipedia : Le Mort-Homme</a>" },
    { img:"cartes_postales/mort_homme_attaque_francaise_1917.png",
      title:"Contre-attaque française — août 1917",
      desc:"Le 20 août 1917, les Français reprennent le Mort-Homme. Vingt-trois ans plus tard, en juin 1940, Alban Rouzaud et ses camarades passent devant la pancarte et repartent vers l'arrière — dans le sens inverse de cette contre-attaque. <a href=\"https://fr.wikipedia.org/wiki/Le_Mort-Homme\" target=\"_blank\" style=\"color:#c8a96e\">↗ Wikipedia : Le Mort-Homme</a>" },
    { img:"cartes_postales/mort_homme_julien_bryan.jpg",
      title:"Ambulance américaine au Mort-Homme — 1917",
      desc:"Photo de Julien Bryan (Ambulance 646, 1917). Les brancardiers et ambulanciers qui ramassaient les blessés sur cette butte. En 1940, Buisson sera lui aussi évacué par un motocycliste providentiel après avoir été touché. <a href=\"https://fr.wikipedia.org/wiki/Le_Mort-Homme\" target=\"_blank\" style=\"color:#c8a96e\">↗ Wikipedia : Le Mort-Homme</a>" },
    { img:"cartes_postales/mort_homme_memorial.jpg",
      title:"Mémorial du Mort-Homme — squelette drapé (1922)",
      desc:"Le monument inauguré en 1922 au sommet de la butte : un squelette drapé dans un linceul tenant le drapeau français, sculpté par Jacques Froment-Meurice. Alban Rouzaud passe devant ce mémorial en juin 1940 — 18 ans après son inauguration, la France est de nouveau en débâcle. <a href=\"https://fr.wikipedia.org/wiki/Le_Mort-Homme\" target=\"_blank\" style=\"color:#c8a96e\">↗ Wikipedia : Le Mort-Homme</a>" }
  ]}
],
